use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store under `last-input`.
        state_rw::put("last-input", &feed_url);

        // Read the clock.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. Transport failures are values; an
        // out-of-allowlist host traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                if n > u32::MAX as usize {
                    u32::MAX
                } else {
                    n as u32
                }
            }
            Err(_) => 0,
        };

        // Notify. The contract requires `notified == true`, so retry a bounded
        // number of times and trap rather than emit a violating report.
        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
